                if (r, c) not in outside:
                    outside.add((r, c))
                    stack.append((r, c))
    while stack:
        y, x = stack.pop()
        for ny, nx in ((y-1,x), (y+1,x), (y,x-1), (y,x+1)):
            if (0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 0
                    and (ny,nx) not in outside):
                outside.add((ny,nx))
                stack.append((ny,nx))

    # Each remaining zero component is a cavity. Find its adjacent 1-component.
    seen1 = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 1 and (r,c) not in seen1:
                q = [(r,c)]
                seen1.add((r,c))
                comp = set()
                while q:
                    y,x = q.pop()
                    comp.add((y,x))
                    for ny,nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                        if (0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 1
                                and (ny,nx) not in seen1):
                            seen1.add((ny,nx))
                            q.append((ny,nx))
                components.append(comp)

    unseen = {(r,c) for r in range(h) for c in range(w)
              if grid[r][c] == 0 and (r,c) not in outside}
    while unseen:
        start = unseen.pop()
        q = [start]
        region = {start}
        while q:
